/* 堆疊長條圖（每月件數依項目分色）：series = [{name, vals, color}]，下方附圖例 */
// 顏色沿用月曆的項目色（TYPE_COLOR）
const TYPE_COLOR_MORE = ['#319795', '#dd6b20', '#718096', '#b83280'];
function stackBars(id, idx, lgd, labels, series, unit) {
  const tot = labels.map((_, i) => series.reduce((a, s) => a + s.vals[i], 0)), mx = Math.max(1, ...tot);
  $(id).innerHTML = labels.map((l, i) => {
    const segs = series.filter(s => s.vals[i] > 0);
    const tip = l + '：' + tot[i] + ' ' + unit + (segs.length ? '（' + segs.map(s => s.name + ' ' + s.vals[i]).join('、') + '）' : '');
    // 由上往下排：最後一個項目在最上面，第一個項目在最底下
    return '<div class="b" title="' + esc(tip) + '"><span>' + (tot[i] || '') + '</span>' +
      segs.slice().reverse().map((s, k) => '<i class="sg' + (k === 0 ? ' top' : '') + '" style="height:' + (s.vals[i] / mx * 100) + '%;background:' + s.color + '"></i>').join('') + '</div>';
  }).join('');
  $(idx).innerHTML = labels.map(l => '<div>' + l + '</div>').join('');
  $(lgd).innerHTML = series.map(s => '<span><i style="background:' + s.color + '"></i>' + esc(s.name) + ' ' + s.vals.reduce((a, b) => a + b, 0) + '</span>').join('');
}
