  let more = 0;
  const series = types.map(t => ({ name: t, color: TYPE_COLOR[t] || TYPE_COLOR_MORE[more++ % TYPE_COLOR_MORE.length],
    vals: Array.from({ length: 12 }, (_, i) => live.filter(c => c[SI.type] === t && c[SI.m] === i + 1).length) })).filter(s => s.vals.some(v => v));
  stackBars('stMonth', 'stMonthX', 'stMonthLgd', Array.from({ length: 12 }, (_, i) => (i + 1) + '月'), series, '件');
